def load() -> pd.DataFrame:
    import glob
    import pandas as pd

    patterns = [
        'data/wildfire/input/*WeatherEvents*',
        'data/wildfire/input/**/*WeatherEvents*',
        'data/wildfire/input/*weatherevents*',
        'data/wildfire/input/**/*weatherevents*',
    ]
    rows = []
    for pat in patterns:
        for p in glob.glob(pat, recursive=True):
            rows.append({'pattern': pat, 'path': p, 'basename': p.split('/')[-1]})

    df = pd.DataFrame(rows)
    if df.empty:
        return pd.DataFrame(columns=['pattern', 'path', 'basename'])

    return df.drop_duplicates().sort_values(['basename', 'path']).reset_index(drop=True)

